inline const SSY *GetSSY(const void *buf) {
  return ::flatbuffers::GetRoot<SSY>(buf);
}

inline const SSY *GetSizePrefixedSSY(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SSY>(buf);
}

inline const char *SSYIdentifier() {
  return "$SSY";
}

inline bool SSYBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SSYIdentifier());
}

inline bool SizePrefixedSSYBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SSYIdentifier(), true);
}

template <bool B = false>
inline bool VerifySSYBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SSY>(SSYIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSSYBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SSY>(SSYIdentifier());
}

inline void FinishSSYBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SSY> root) {
  fbb.Finish(root, SSYIdentifier());
}

inline void FinishSizePrefixedSSYBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SSY> root) {
  fbb.FinishSizePrefixed(root, SSYIdentifier());
}

